module.exports = [
  {"id":"kopelman-7-1-ambiente-comportamentos-e-obesidade","pos":67,"tema":"Obesidade: Definição e Epidemiologia","origem":"03_genetica_e_causas_secundarias/ambiente_comportamentos_e_obesidade_modelo_conceitual__ClinicalObesity_p102_PT.png","depoisDe":"A abordagem deve ser **crônica, longitudinal e livre de estigma**.","legenda":"Ambiente urbano e obesidade: fatores biofísicos, tecnológicos, econômicos, socioculturais e demográficos moldam o ambiente construído, o social e o acesso; com as características individuais, eles orientam os comportamentos ligados à energia, que levam à obesidade e às suas complicações. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 7.1."},
  {"id":"guyton-72-2-neuronios-pomc-e-agrp-do-nucleo-arqueado","pos":68,"tema":"Fisiopatologia da Obesidade","origem":"01_regulacao_do_apetite_e_balanco_energetico/neuronios_pomc_e_agrp_do_nucleo_arqueado__Guyton_p2578.png","depoisDe":"perpetuando a hiperfagia apesar de leptina elevada.","legenda":"Núcleo arqueado: neurônios POMC/CART liberam α-MSH, que ativa o MCR-4 (MC4R) dos neurônios do núcleo paraventricular (NPV) e reduz a ingestão; neurônios AgRP/NPY, estimulados pela grelina, aumentam a ingestão. Insulina, leptina e CCK inibem AgRP/NPY e estimulam POMC/CART. Fonte: Hall JE, Guyton & Hall Tratado de Fisiologia Médica, 13ª ed., fig. 72-2."},
  {"id":"kopelman-11-1-subcutaneo-abdominal-e-gluteofemoral","pos":68,"tema":"Fisiopatologia da Obesidade","origem":"02_tecido_adiposo_e_adipocinas/compartimentos_do_tecido_adiposo_subcutaneo_abdominal_e_gluteofemoral__ClinicalObesity_p160_PT.png","depoisDe":"O tecido adiposo é órgão **endócrino ativo**, secretor de adipocinas.","legenda":"Tecido adiposo subcutâneo abdominal (ASAT) e gluteofemoral (GSAT): no ganho de peso, o ASAT cresce por hipertrofia e capta e libera gordura de imediato; o GSAT cresce por hiperplasia e armazena a longo prazo os triglicerídeos da VLDL e os ácidos graxos não esterificados (AGNE). Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 11.1."},
  {"id":"kopelman-20-2-adaptacoes-fisiologicas-a-perda-de-peso","pos":68,"tema":"Fisiopatologia da Obesidade","origem":"01_regulacao_do_apetite_e_balanco_energetico/adaptacoes_fisiologicas_a_perda_de_peso__ClinicalObesity_p279_PT.png","depoisDe":"- Somam-se sinais **não homeostáticos**: motivação, recompensa e atenção.","legenda":"Adaptações à perda de peso: (a) sobem grelina e fome e caem insulina, leptina, CCK, PYY e GLP-1; com menos atividade simpática (SNS), cai o gasto (GET, total; ETA, efeito térmico dos alimentos; TMR, repouso; GEAF, atividade física), e surge um hiato energético; (b) dieta, exercício e medicamentos o compensam. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 20.2."},
  {"id":"greenspan-20-2-secrecoes-do-tecido-adiposo","pos":68,"tema":"Fisiopatologia da Obesidade","origem":"02_tecido_adiposo_e_adipocinas/secrecoes_do_tecido_adiposo_e_metabolismo__Greenspan_p761_PT.png","depoisDe":"É órgão endócrino: produz **leptina e adiponectina**.","legenda":"Secreções do tecido adiposo: leptina (apetite e balanço energético, reprodução, sensibilidade à insulina, imunidade), adiponectina e citocinas inflamatórias (ações opostas na sensibilidade à insulina), angiotensinogênio (pressão arterial) e PAI-1, inibidor do ativador do plasminogênio (hemostasia). Fonte: traduzida de Gardner DG, Shoback D, Greenspan's Basic & Clinical Endocrinology, 10ª ed., fig. 20-2."},
  {"id":"kopelman-9-1-principios-do-balanco-energetico","pos":68,"tema":"Fisiopatologia da Obesidade","origem":"01_regulacao_do_apetite_e_balanco_energetico/principios_do_balanco_energetico__ClinicalObesity_p126_PT.png","depoisDe":"O balanço positivo que produz obesidade é de pequena magnitude e longa duração, e não de excessos episódicos.","legenda":"Balanço energético: da energia ingerida, parte se perde nas fezes e na urina; o restante circula como glicose, ácidos graxos e aminoácidos, vai para os estoques (gordura 77%, proteína 22%, glicogênio < 1%) ou é gasto na taxa metabólica basal, na atividade física e na termogênese, saindo como calor. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 9.1."},
  {"id":"williams-39-7-circuitos-de-recompensa-no-controle-alimentar","pos":68,"tema":"Fisiopatologia da Obesidade","origem":"01_regulacao_do_apetite_e_balanco_energetico/circuitos_de_recompensa_no_controle_alimentar__Williams_p1958_PT.png","depoisDe":"A **grelina aumenta a dopamina no accumbens** e a **resistência à leptina reduz a inibição dopaminérgica** — duas vias de conexão entre o eixo homeostático e o hedônico.","legenda":"Circuitos de recompensa: neurônios de dopamina (DA) da área tegmental ventral (VTA), com receptores de leptina (LepRb) e grelina (GHSR), projetam ao núcleo accumbens (NAc; desejo, prazer), que estimula a ingestão, e à amígdala (aversão), que a inibe; LHA, área hipotalâmica lateral; OX, orexina. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 39.7."},
  {"id":"kopelman-10-1-adipocinas-inflamacao-gordura-ectopica","pos":68,"tema":"Fisiopatologia da Obesidade","origem":"02_tecido_adiposo_e_adipocinas/adipocinas_inflamacao_e_gordura_ectopica_na_resistencia_insulinica__ClinicalObesity_p146_PT.png","depoisDe":"A ativação de **NF-κB e JNK** produz a resistência insulínica.","legenda":"Hipertrofia do tecido adiposo visceral (TAV): macrófagos atraídos pela MCP-1, TNF-α, IL-6, queda da adiponectina e ácidos graxos não esterificados (AGNE) contribuem para a esteatose hepática, muscular (ceramidas e diacilglicerol, DAG) e pancreática, com resistência à insulina e falência da célula β. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 10.1."},
  {"id":"kopelman-3-1-risco-ao-longo-da-vida","pos":68,"tema":"Fisiopatologia da Obesidade","origem":"08_obesidade_infantil_e_cancer/origens_desenvolvimentistas_do_risco_ao_longo_da_vida__ClinicalObesity_p46_PT.png","depoisDe":"Esses achados fundamentam a atenção **pré-concepcional** e à nutrição materna.","legenda":"Risco de doenças crônicas não transmissíveis ao longo da vida: fatores genéticos, epigenéticos e ambientais passam entre gerações, e a plasticidade é maior no início da vida (mãe e lactente, infância e adolescência), quando intervir é mais eficaz; no adulto, as intervenções têm efeito limitado. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 3.1."},
  {"id":"williams-39-1-eixo-cerebro-intestino-tecido-adiposo","pos":69,"tema":"Regulação do Apetite","origem":"01_regulacao_do_apetite_e_balanco_energetico/eixo_cerebro_intestino_tecido_adiposo_controle_da_ingestao__Williams_p1948_PT.png","depoisDe":"O desequilíbrio entre esses sistemas — reforçado pelo ambiente obesogênico — favorece a hiperfagia.","legenda":"Eixo cérebro–intestino–tecido adiposo: leptina, insulina, grelina, PYY, CCK, GLP-1, amilina, nutrientes e aferências autonômicas chegam ao hipotálamo e ao tronco encefálico, que respondem com eferências comportamentais, endócrinas (via hipófise) e autonômicas para gordura, músculo, fígado e intestino. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 39.1."},
  {"id":"apovian-2-4-saciedade-e-recompensa-no-snc","pos":69,"tema":"Regulação do Apetite","origem":"01_regulacao_do_apetite_e_balanco_energetico/controle_central_da_ingestao_gasto_energetico_e_recompensa__ClinicalManagementObesity_p34_PT.png","depoisDe":"o estresse e o sono insuficiente deslocam o equilíbrio para o lado orexígeno.","legenda":"Saciedade e recompensa no SNC: pelo vago e por nervos espinhais, a refeição gera saciedade, que inibe a recompensa e a ingestão; leptina e grelina agem no núcleo arqueado (ARC), na área hipotalâmica lateral (LHA) e na área tegmental ventral (VTA), que ativa o núcleo accumbens (Nac); AMY, amígdala. Fonte: traduzida de Apovian CM, Aronne LJ, Barenbaum SR, Clinical Management of Obesity, 3ª ed., fig. 2.4."},
  {"id":"williams-39-8-circuitos-do-tronco-encefalico","pos":69,"tema":"Regulação do Apetite","origem":"01_regulacao_do_apetite_e_balanco_energetico/circuitos_do_tronco_encefalico_no_controle_alimentar__Williams_p1959_PT.png","depoisDe":"tem efeito **incretínico-like** e ativa o vago |","legenda":"Circuitos do tronco encefálico: CCK, GLP-1, amilina e PYY agem na área postrema (AP) e, pelo vago, no núcleo do trato solitário (NTS), ligado ao hipotálamo, ao núcleo parabraquial (PBN; neurônios CGRP → amígdala, aversão) e ao núcleo motor dorsal do vago (DMV); o GDF15, da inflamação sistêmica, age na AP. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 39.8."},
  {"id":"kopelman-8-2-sinais-tonicos-e-episodicos-do-apetite","pos":69,"tema":"Regulação do Apetite","origem":"01_regulacao_do_apetite_e_balanco_energetico/sinais_tonicos_e_episodicos_do_apetite__ClinicalObesity_p116_PT.png","depoisDe":"o freio que ajuda a explicar a resistência à leptina na obesidade.","legenda":"Controle do apetite por sinais tônicos e episódicos: a massa magra, pela taxa metabólica de repouso, aumenta o impulso para comer, e a massa gorda, pela leptina, o inibe de forma contínua; o trato gastrintestinal emite sinais ligados às refeições, a grelina (estimula) e CCK, PYY e GLP-1 (inibem). Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 8.2."},
  {"id":"netter-7-26-avaliacao-antropometrica-obesidade","pos":70,"tema":"Obesidade: Avaliação Clínica e Diagnóstico","origem":"04_diagnostico_classificacao_estadiamento/avaliacao_antropometrica_causas_e_comorbidades_da_obesidade__Netter_p222_PT.png","depoisDe":"ão com risco cardiovascular**; a relação cintura-estatura (> 0,5) também é útil e simples.","formato":"jpg","legenda":"Avaliação da obesidade: antropometria (peso, altura, cintura e quadril; relação cintura-quadril normal na mulher < 0,85), causas (alta ingestão calórica, distúrbios hipotalâmicos, síndrome de Cushing, corticoides, insulinoma), hipertrofia ou hiperplasia de adipócitos, cardiomegalia e hepatomegalia. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 7-26."},
  {"id":"kopelman-26-1-acantose-nigricans-cervical","pos":70,"tema":"Obesidade: Avaliação Clínica e Diagnóstico","origem":"08_obesidade_infantil_e_cancer/acantose_nigricante_cervical_em_adolescente__ClinicalObesity_p353.png","depoisDe":"e exame cutâneo — **acantose nigricans, estrias violáceas, hirsutismo**.","legenda":"Acantose nigricans na nuca e na face lateral do pescoço de adolescente com obesidade: pele espessada, aveludada e escurecida, com pregas acentuadas e um acrocórdon à esquerda. É sinal clínico de resistência à insulina. Fonte: Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 26.1."},
  {"id":"apovian-3-1-comorbidades-da-obesidade","pos":71,"tema":"Obesidade: Comorbidades e Gestação","origem":"05_complicacoes/comorbidades_associadas_a_obesidade__ClinicalManagementObesity_p50_PT.png","depoisDe":"vários **cânceres** (endométrio, mama pós-menopausa, cólon, rim, esôfago, pâncreas, entre outros).","legenda":"Complicações da obesidade por órgão e sistema: hipertensão intracraniana idiopática, AVC, catarata, doença coronariana, diabetes, dislipidemia, hipertensão, apneia e hipoventilação, doença hepática esteatótica, doença biliar, SOMP (antiga SOP), infertilidade, osteoartrite, gota, estase venosa e câncer. Fonte: traduzida e adaptada de Apovian CM, Aronne LJ, Barenbaum SR, Clinical Management of Obesity, 3ª ed., fig. 3.1."},
  {"id":"kopelman-15-1-polissonografia-apneia-obstrutiva-grave","pos":71,"tema":"Obesidade: Comorbidades e Gestação","origem":"05_complicacoes/polissonografia_apneia_obstrutiva_do_sono_grave__ClinicalObesity_p203_PT.png","depoisDe":"- **C** — **≥ 15 eventos por hora**, critério que estabelece o diagnóstico **na ausência de sintomas**.","legenda":"Polissonografia de 5 minutos na apneia obstrutiva grave: o fluxo aéreo cessa enquanto os movimentos torácicos e abdominais continuam (evento obstrutivo); cada pausa termina em microdespertar (EEG e EMG) e é seguida de queda da saturação de O2. EOG, eletro-oculograma; EMG, eletromiograma. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 15.1."},
  {"id":"vilar-52-2-adiposidade-abdominal-e-somp","pos":71,"tema":"Obesidade: Comorbidades e Gestação","origem":"05_complicacoes/adiposidade_abdominal_e_sindrome_dos_ovarios_policisticos__Vilar_p941.png","depoisDe":"na fertilização in vitro, **mais aneuploidias e pior qualidade embrionária**.","legenda":"Adiposidade visceral e SOMP (antiga SOP) em ciclo vicioso: o excesso de andrógenos favorece a gordura visceral, cujas adipocinas (↓ adiponectina; ↑ TNF-α, IL-6 e leptina) agravam a resistência à insulina; a hiperinsulinemia, por sua vez, estimula a produção de andrógenos no ovário e na adrenal. Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 52.2."},
  {"id":"kopelman-16-1-canceres-associados-a-obesidade","pos":71,"tema":"Obesidade: Comorbidades e Gestação","origem":"08_obesidade_infantil_e_cancer/canceres_associados_ao_sobrepeso_e_obesidade__ClinicalObesity_p222_PT.png","depoisDe":"**tireoide**, **mieloma múltiplo** e **meningioma**.","legenda":"Cânceres associados ao sobrepeso e à obesidade segundo o Instituto Nacional do Câncer dos EUA (NCI): meningioma, adenocarcinoma de esôfago, tireoide, mama na pós-menopausa, mieloma múltiplo, fígado, vesícula biliar, estômago proximal, rim, pâncreas, endométrio, ovário e cólon e reto. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 16.1."},
  {"id":"greenspan-20-1-sistema-leptina-melanocortina","pos":72,"tema":"Obesidade Sindrômica e Monogênica","origem":"03_genetica_e_causas_secundarias/sistema_leptina_melanocortina_do_balanco_energetico__Greenspan_p759_PT.png","depoisDe":"Todo defeito monogênico clássico cai em um ponto dela — e é isso que explica quem responde a qual tratamento.","legenda":"Sistema leptina–melanocortina: a leptina do tecido adiposo estimula, via LepR, os neurônios POMC e inibe os AgRP/NPY do núcleo arqueado; no núcleo paraventricular, o α-MSH ativa e o AgRP bloqueia o MC4R, cuja ativação reduz a ingestão e aumenta o gasto energético. Fonte: traduzida de Gardner DG, Shoback D, Greenspan's Basic & Clinical Endocrinology, 10ª ed., fig. 20-1."},
  {"id":"williams-39-2-processamento-da-pomc","pos":72,"tema":"Obesidade Sindrômica e Monogênica","origem":"03_genetica_e_causas_secundarias/processamento_da_pomc_pelas_pro_hormonio_convertases__Williams_p1950_PT.png","depoisDe":"— a assinatura laboratorial da enzima que não cliva. **Responde a setmelanotide.**","legenda":"Processamento da POMC: após a retirada do peptídeo sinal, a PC1/3 (gene PCSK1) gera ACTH e β-lipotrofina (β-LPH) na hipófise anterior; no lobo intermediário e no núcleo arqueado, PC1/3 e PC2 liberam α-MSH, γ-MSH, CLIP (peptídeo do lobo intermediário semelhante à corticotrofina), γ-LPH e β-endorfina. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 39.2."},
  {"id":"williams-39-4-deficiencia-de-pomc-cabelos-ruivos","pos":72,"tema":"Obesidade Sindrômica e Monogênica","origem":"03_genetica_e_causas_secundarias/deficiencia_congenita_de_pomc_obesidade_e_cabelos_ruivos__Williams_p1952.png","depoisDe":"e **braquidactilia com cálcio baixo** (Albright).","legenda":"Deficiência congênita de POMC em criança: obesidade grave de início precoce e cabelos ruivos (falta de α-MSH); a síndrome inclui insuficiência adrenal por falta de ACTH. Fonte: Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 39.4."},
  {"id":"apovian-8-2-tamanho-das-porcoes","pos":73,"tema":"Dieta e Exercício Físico na Obesidade","origem":"06_tratamento_clinico_e_farmacologico/recursos_visuais_para_tamanho_das_porcoes__ClinicalManagementObesity_p172_PT.png","depoisDe":"pessoas com obesidade subestimam a própria ingestão em até 40%, o que fundamenta o automonitoramento.","legenda":"Referências visuais para estimar porções: bola de beisebol ≈ 1 xícara (salada verde, fruta média, batata assada); mão em concha ≈ ½ xícara (fruta picada, legumes cozidos, massa, arroz); ovo ≈ ¼ xícara (frutas secas); baralho ≈ 85 g de carne ou ave; talão de cheques ≈ 85 g de peixe; dados ≈ 42 g de queijo. Fonte: traduzida de Apovian CM, Aronne LJ, Barenbaum SR, Clinical Management of Obesity, 3ª ed., fig. 8.2."},
  {"id":"williams-40-2-componentes-do-gasto-energetico-diario","pos":73,"tema":"Dieta e Exercício Físico na Obesidade","origem":"01_regulacao_do_apetite_e_balanco_energetico/componentes_do_gasto_energetico_diario__Williams_p1973_PT.png","depoisDe":"**exercício físico** é a atividade planejada, repetitiva e estruturada, definida por frequência, duração e intensidade.","legenda":"Componentes do gasto energético diário: a taxa metabólica de repouso (sono e vigília) é a maior parcela, seguida da atividade física, que soma o exercício intencional e a NEAT (termogênese da atividade não ligada ao exercício, como andar e ficar de pé), e do efeito térmico dos alimentos. Esquema sem escala. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 40.2."},
  {"id":"kopelman-19-1-cadeia-comportamental","pos":73,"tema":"Dieta e Exercício Físico na Obesidade","origem":"06_tratamento_clinico_e_farmacologico/cadeia_comportamental_na_terapia_cognitivo_comportamental__ClinicalObesity_p260_PT.png","depoisDe":"**A abordagem deve ser adaptada ao contexto étnico, cultural, socioeconômico e educacional do paciente.**","legenda":"Cadeia comportamental (terapia cognitivo-comportamental): 12 elos vão de ficar acordado até tarde vendo uma série a comer biscoitos e sentir culpa; as elipses marcam onde romper a cadeia (preparar o café da manhã na véspera, comer refeição congelada com porção controlada, conversar com um amigo ou colega). Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 19.1."},
  {"id":"diretriz2025-tabela-4-efeitos-dos-antiobesidade","pos":74,"tema":"Tratamento Farmacológico da Obesidade","origem":"06_tratamento_clinico_e_farmacologico/efeitos_dos_antiobesidade_aprovados_no_brasil_sobre_complicacoes__Diretriz2025_p17.png","depoisDe":"fluoxetina de curto prazo e lisdexanfetamina no TCAP).","legenda":"Efeitos dos seis antiobesidade aprovados no Brasil sobre as complicações, pela cor do nível de evidência; o vermelho (sibutramina em DCV e IC) marca risco cardiovascular em pacientes de alto risco. SOP equivale à SOMP e MASLD à DHEM; DRC, doença renal crônica; DCV, doença cardiovascular; IC, insuficiência cardíaca. Fonte: Saraiva JFK et al., Diretriz Brasileira Baseada em Evidências de 2025 para o Manejo da Obesidade (ABESO/SBD/SBC/SBEM/ABS), tabela 4."},
  {"id":"apovian-2-5-naltrexona-bupropiona","pos":74,"tema":"Tratamento Farmacológico da Obesidade","origem":"06_tratamento_clinico_e_farmacologico/mecanismo_da_naltrexona_bupropiona__ClinicalManagementObesity_p35_PT.png","depoisDe":"a naltrexona antagoniza receptores opioides nesse circuito.","legenda":"Naltrexona/bupropiona: a bupropiona, via dopamina (DA) e norepinefrina (NE), estimula o neurônio POMC, que libera α-MSH sobre o MC4R (receptor de melanocortina 4) e reduz o apetite; a naltrexona bloqueia a autoinibição opioide do POMC (β-endorfina) e potencializa a bupropiona. AgRP/NPY estimula o apetite. Fonte: traduzida de Apovian CM, Aronne LJ, Barenbaum SR, Clinical Management of Obesity, 3ª ed., fig. 2.5."},
  {"id":"apovian-2-6-acoes-do-glp1","pos":74,"tema":"Tratamento Farmacológico da Obesidade","origem":"06_tratamento_clinico_e_farmacologico/acoes_do_glp1_e_dos_agonistas_na_perda_de_peso__ClinicalManagementObesity_p37_PT.png","depoisDe":"retarda o esvaziamento gástrico; atenua o sistema de recompensa.","legenda":"Ações do GLP-1 e dos agonistas do seu receptor: menos apetite e mais saciedade no cérebro, esvaziamento gástrico mais lento, mais insulina e menos glucagon no pâncreas e efeitos em fígado, tecido adiposo, músculo, rim, coração e vasos, com queda de peso, pressão arterial, glicemia e lípides. Fonte: traduzida e adaptada de Apovian CM, Aronne LJ, Barenbaum SR, Clinical Management of Obesity, 3ª ed., fig. 2.6."},
  {"id":"vilar-80-6-balao-intragastrico","pos":75,"tema":"Tratamento Cirúrgico da Obesidade","origem":"07_cirurgia_bariatrica_metabolica/balao_intragastrico__Vilar_p1443.png","depoisDe":"a perda é **reversível** se não houver MEV depois da retirada.","legenda":"Balão intragástrico posicionado no estômago: prótese de silicone cheia de líquido que ocupa parte do volume gástrico, distende a parede e aumenta a saciedade; é temporária (6 a 12 meses). Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 80.6."},
  {"id":"williams-40-3-esquemas-cirurgias-bariatricas","pos":75,"tema":"Tratamento Cirúrgico da Obesidade","origem":"07_cirurgia_bariatrica_metabolica/esquemas_das_cirurgias_bariatricas_rygb_banda_sleeve_dbp_ds__Williams_p1982.png","depoisDe":"as técnicas de escolha são o BGYR e a gastrectomia vertical, e o duodenal switch fica como alternativa, sobretudo revisional.","legenda":"Técnicas bariátricas: (A) bypass gástrico em Y de Roux; (B) banda gástrica ajustável; (C) gastrectomia vertical; (D) derivação biliopancreática de Scopinaro; (E) derivação biliopancreática com duodenal switch. Banda e Scopinaro deixaram de ser recomendadas pela Resolução CFM 2.429/2025. Fonte: Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 40.3."},
  {"id":"apovian-10-11-bypass-gastrico-y-de-roux-alcas","pos":75,"tema":"Tratamento Cirúrgico da Obesidade","origem":"07_cirurgia_bariatrica_metabolica/derivacao_gastrica_em_y_de_roux_alcas__ClinicalManagementObesity_p304_PT.png","depoisDe":"o que ele evita é o **refluxo biliar** para o pouch e o esôfago.","legenda":"Bypass gástrico em Y de Roux: a alça alimentar é levada até a bolsa gástrica através do mesocólon transverso (via retrocólica); a alça biliopancreática conduz bile e suco pancreático até a enteroanastomose, de onde segue o canal comum (alça comum). Fonte: traduzida de Apovian CM, Aronne LJ, Barenbaum SR, Clinical Management of Obesity, 3ª ed., fig. 10.11."},
  {"id":"essencial-89-5-derivacao-biliopancreatica-scopinaro","pos":76,"tema":"Suplementação Nutricional Pós-Bariátrica","origem":"07_cirurgia_bariatrica_metabolica/derivacao_biliopancreatica_de_scopinaro__Essencial_p1219.png","depoisDe":"| Derivação biliopancreática | Proteínas, vitaminas lipossolúveis (A, D, E, K), B1, B12, folato, cálcio, magnésio, ferro, zinco e cobre |","legenda":"Derivação biliopancreática de Scopinaro (hoje não recomendada): após gastrectomia distal, o alimento percorre 200 cm de íleo (alça alimentar) e só encontra bile e suco pancreático nos 50 cm finais (alça comum), o que explica a má absorção de gordura, vitaminas lipossolúveis e proteína. Fonte: adaptada de Sales P, Halpern A, Cercato C, O Essencial em Endocrinologia, fig. 89.5."},
  {"id":"golan-26-4-eixo-tireoidiano-graves-hashimoto","pos":77,"tema":"Tireoide: Avaliação da Função e Imagem","origem":"02_avaliacao_funcao_e_exames/eixo_hht_normal_doenca_de_graves_e_hashimoto__Golan_p449.png","depoisDe":"| ↑ | ↑ | Resistência a hormônio tireoidiano / TSHoma (raro) |","legenda":"Eixo hipotálamo-hipófise-tireoide: normal (A), doença de Graves (B) e tireoidite de Hashimoto (C). Em B, o autoanticorpo estimulador (TRAb) eleva o hormônio tireoidiano, que suprime TRH e TSH; em C, a destruição autoimune reduz o hormônio, e TRH e TSH sobem. Traço grosso: efeito maior; tracejado: menor. Fonte: Golan DE et al., Princípios de Farmacologia, fig. 26.4."},
  {"id":"williams-14-1-ultrassom-da-tireoide-normal","pos":77,"tema":"Tireoide: Avaliação da Função e Imagem","origem":"01_anatomia_embriologia_histologia/ultrassom_e_mapa_anatomico_da_tireoide_normal__Williams_p537_PT.png","depoisDe":"e avalia **linfonodos cervicais**. Não usa radiação; ideal para seguimento seriado.","legenda":"Tireoide normal ao ultrassom transversal (A) e mapa anatômico correspondente (B): lobos (T) dos lados da traqueia (TR), com carótida comum (C) e jugular interna (J) por fora. Siglas do original em inglês: SM, músculos pré-tireoidianos; SCM, esternocleidomastóideo; LC, longo do pescoço. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 14.1."},
  {"id":"greenspan-7-25-curvas-de-captacao-de-iodo","pos":77,"tema":"Tireoide: Avaliação da Função e Imagem","origem":"02_avaliacao_funcao_e_exames/curvas_de_captacao_de_iodo_radioativo_em_24h__Greenspan_p220_PT.png","depoisDe":"com ordenha e descarte do leite por 3–4 dias após I-123 e por 36 horas após Tc-99m (ATA 2026).","legenda":"Curvas típicas de captação tireoidiana de iodo-123 ao longo de 24 horas: no normal, chega a cerca de 20%; é alta no hipertireoidismo e mínima no hipotireoidismo. Na alta renovação (turnover rápido do iodo), a captação atinge o pico por volta de 6 h e depois cai. Fonte: traduzida de Gardner DG, Shoback D, Greenspan's Basic & Clinical Endocrinology, 10ª ed., fig. 7-25."},
  {"id":"vilar-21-8-sindrome-do-eutireoideo-doente","pos":77,"tema":"Tireoide: Avaliação da Função e Imagem","origem":"02_avaliacao_funcao_e_exames/sindrome_do_eutireoideo_doente_variacao_hormonal__Vilar_p375.png","depoisDe":"ambulatorialmente** (TEEM 2025 q. 31; TEEM 2019 q. 13).","legenda":"Síndrome do eutireóideo doente: com o agravamento da doença, o T3 cai e o T3 reverso (rT3) sobe; na fase grave, T4 e T4 livre (FT4) também caem. Na recuperação, o TSH sobe transitoriamente acima do normal, e os hormônios voltam à faixa normal. Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 21.8."},
  {"id":"netter-2-16-causas-hipotireoidismo-primario-central","pos":78,"tema":"Hipotireoidismo","origem":"03_hipotireoidismo/causas_de_hipotireoidismo_primario_e_central__Netter_p64_PT.png","depoisDe":"hipofisite (incluindo por ICI), trauma, doenças infiltrativas.","formato":"jpg","legenda":"Causas de hipotireoidismo. Primário: pós-tireoidectomia, pós-iodo radioativo (doença de Graves), pós-tireoidite e tireoidite de Hashimoto. Central: infarto hipofisário pós-parto (Sheehan) ou tumor destrutivo, com pan-hipopituitarismo, e deficiência isolada de TSH (p. ex., hipofisite linfocítica). Fonte: traduzida e adaptada de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-16."},
  {"id":"greenspan-7-29-cardiomegalia-derrame-pericardico","pos":78,"tema":"Hipotireoidismo","origem":"03_hipotireoidismo/cardiomiopatia_hipotireoidea_radiografia_e_ecocardiograma__Greenspan_p227_PT.png","depoisDe":"Forma grave/descompensada → **coma mixedematoso**.","formato":"jpg","legenda":"Derrame pericárdico no hipotireoidismo: área cardíaca aumentada (A) e normal 6 meses após levotiroxina (B); no ecocardiograma em modo M, o derrame (C) desaparece com o tratamento (D). PT: parede torácica; PVD/CVD: parede/cavidade do VD; SIV: septo; CVE/PPVE: cavidade/parede posterior do VE. Fonte: traduzida de Gardner DG, Shoback D, Greenspan's Basic & Clinical Endocrinology, 10ª ed., fig. 7-29."},
  {"id":"vilar-27-6-algoritmo-hipotireoidismo","pos":78,"tema":"Hipotireoidismo","origem":"03_hipotireoidismo/algoritmo_diagnostico_e_tratamento_do_hipotireoidismo__Vilar_p472.png","depoisDe":"**Anti-TG, anti-TPO e ultrassom NÃO são necessários de rotina.**","legenda":"Diagnóstico do hipotireoidismo pelo TSH e T4 livre (FT4): primário (levotiroxina), central (RM de sela; tumor ou lesão infiltrativa → cirurgia ou radioterapia), subclínico (levotiroxina ou observar) ou excluído. Não mostra a avaliação dos demais eixos (cortisol), que precede a levotiroxina no central. Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 27.6."},
  {"id":"netter-2-14-manifestacoes-hipotireoidismo-adulto","pos":78,"tema":"Hipotireoidismo","origem":"03_hipotireoidismo/manifestacoes_clinicas_do_hipotireoidismo_no_adulto__Netter_p62_PT.png","depoisDe":"| Baixa estatura (na infância) | |","formato":"jpg","legenda":"Manifestações do hipotireoidismo no adulto: letargia e lentificação mental, edema facial e palpebral, língua espessa, voz rouca, intolerância ao frio, pele seca, fria e amarelada (carotenemia), pulso lento, cardiomegalia, hipertensão diastólica, menorragia, ascite e reflexos com relaxamento lento. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-14."},
  {"id":"vilar-34-6-ultrassom-hashimoto","pos":78,"tema":"Hipotireoidismo","origem":"03_hipotireoidismo/ultrassom_na_tireoidite_de_hashimoto__Vilar_p588.png","depoisDe":"atrófica**.","formato":"jpg","legenda":"Ultrassonografia na tireoidite de Hashimoto: glândula difusamente aumentada, de textura heterogênea e hipoecogênica (A e B), com pseudonódulos (C) e parênquima hipervascularizado ao Doppler colorido (D). Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 34.6."},
  {"id":"netter-2-8-manifestacoes-da-doenca-de-graves","pos":79,"tema":"Tireotoxicose: Abordagem e Diagnóstico Diferencial","origem":"04_hipertireoidismo_graves/manifestacoes_clinicas_da_doenca_de_graves__Netter_p56_PT.png","depoisDe":"| **Bócio difuso** (específico de Graves) | Aumento cervical, rouquidão, disfagia |","formato":"jpg","legenda":"Manifestações clínicas da doença de Graves: sinais gerais de tireotoxicose (sudorese, perda de peso, taquicardia, tremor, pele quente e úmida, fraqueza muscular, oligomenorreia) e achados próprios da doença (exoftalmia, bócio com frêmito e sopro, mixedema pré-tibial e baqueteamento digital). Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-8."},
  {"id":"netter-2-6-efeitos-do-tsh-na-tireoide","pos":79,"tema":"Tireotoxicose: Abordagem e Diagnóstico Diferencial","origem":"02_avaliacao_funcao_e_exames/efeitos_do_tsh_padroes_de_tsh_t4_t3_e_captacao__Netter_p54_PT.png","depoisDe":"**RM de sela** para identificar e dimensionar o adenoma.","formato":"jpg","legenda":"Efeitos do TSH sobre a tireoide: com TSH baixo ou ausente (falência hipofisária), a glândula atrofia, o epitélio folicular fica plano e T4 livre, T3 total e captação de iodo-131 caem; com TSH alto (tumor hipofisário secretor de TSH), há bócio, epitélio colunar com menos coloide e esses valores sobem. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-6."},
  {"id":"vilar-31-4-padroes-cintilograficos","pos":79,"tema":"Tireotoxicose: Abordagem e Diagnóstico Diferencial","origem":"02_avaliacao_funcao_e_exames/padroes_cintilograficos_normal_graves_adenoma_toxico_bmnt__Vilar_p534.png","depoisDe":"| Baixa/ausente | Tireoidite / iodo / factícia | VHS↑ (subaguda), Tg baixa (factícia) |","legenda":"Padrões da cintilografia tireoidiana: (A) normal; (B) doença de Graves, com captação difusa e aumentada; (C) adenoma tóxico, com nódulo hipercaptante (quente) e supressão do restante da glândula; (D) bócio multinodular tóxico, com várias áreas hipercaptantes e captação heterogênea. Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 31.4."},
  {"id":"netter-2-11-patologia-da-tireoide-na-doenca-de-graves","pos":80,"tema":"Doença de Graves (Hipertireoidismo)","origem":"04_hipertireoidismo_graves/patologia_da_tireoide_na_doenca_de_graves__Netter_p59_PT.png","depoisDe":"explicam a **oftalmopatia** e a **dermopatia** (ver capítulo próprio de Oftalmopatia).","formato":"jpg","legenda":"Tireoide na doença de Graves: bócio difuso de tamanho moderado, captação difusa à cintilografia, glândula aumentada (o tracejado marca o tamanho normal) e, à histologia, hiperplasia folicular difusa e áreas de infiltrado linfocitário. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-11."},
  {"id":"imaging-1-5-doppler-colorido-graves","pos":80,"tema":"Doença de Graves (Hipertireoidismo)","origem":"04_hipertireoidismo_graves/doppler_colorido_na_doenca_de_graves__Imaging_p21.png","depoisDe":"**US com Doppler** mostra hipervascularização (\"thyroid inferno\").","formato":"jpg","legenda":"Doença de Graves ao ultrassom com Doppler colorido: hipervascularização difusa do parênquima (\"inferno tireoidiano\") nos cortes transversal (a) e longitudinal (b). P, parênquima; T, traqueia. Fonte: Pozzilli P, Lenzi A, Clarke BL, Young WF Jr, Imaging in Endocrinology, fig. 1.5."},
  {"id":"netter-2-2-anatomia-cirurgica-da-tireoide","pos":80,"tema":"Doença de Graves (Hipertireoidismo)","origem":"01_anatomia_embriologia_histologia/anatomia_da_tireoide_vistas_anterior_e_lateral_nervos_laringeos__Netter_p50_PT.png","depoisDe":"Complicações: **hipoparatireoidismo** (hipocalcemia) e **lesão do nervo laríngeo recorrente** (rouquidão/disfonia); repor LT4 após.","formato":"jpg","legenda":"Vista anterior da tireoide (vasos tireóideos, nervos vagos e laríngeos recorrentes) e vista lateral direita com o lobo rebatido: paratireoides superior e inferior, irrigadas sobretudo pela artéria tireóidea inferior, nervo laríngeo recorrente e ramo externo do laríngeo superior, em risco na tireoidectomia. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-2."},
  {"id":"williams-12-14-mixedema-pre-tibial","pos":80,"tema":"Doença de Graves (Hipertireoidismo)","origem":"04_hipertireoidismo_graves/mixedema_pre_tibial_dermopatia_de_graves__Williams_p476.png","depoisDe":"**acropatia tireoidiana**.","formato":"jpg","legenda":"Dermopatia de Graves: mixedema pré-tibial crônico, com espessamento nodular da pele da perna (A), e extensão aos pés com deformidade grave (B). Fonte: Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 12.14."},
  {"id":"golan-26-5-sitios-de-acao-dos-antitireoidianos","pos":80,"tema":"Doença de Graves (Hipertireoidismo)","origem":"04_hipertireoidismo_graves/sitios_de_acao_dos_farmacos_antitireoidianos__Golan_p450.png","depoisDe":"MIT/DIT.","legenda":"Onde agem os antitireoidianos: perclorato, tiocianato e pertecnetato bloqueiam a captação de iodeto (NIS); tionamidas e iodeto em dose alta inibem a TPO (organificação e acoplamento); o iodeto também impede a liberação hormonal; o I-131 destrói a célula folicular; o PTU inibe a conversão de T4 em T3. Fonte: adaptada de Golan DE et al., Princípios de Farmacologia, fig. 26.5."},
  {"id":"greenspan-7-4-histologia-da-tireoide","pos":82,"tema":"Bócio e Hipertireoidismo por Autonomia (BMN tóxico e adenoma tóxico)","origem":"01_anatomia_embriologia_histologia/histologia_da_tireoide_foliculos_coloide_e_celulas_c__Greenspan_p199.png","depoisDe":"e **prova de função respiratória** com alça inspiratória.","legenda":"Tireoide de rato. A: normal, folículos de epitélio cúbico cheios de coloide e células C parafoliculares entre eles. B: inativa, folículos grandes, coloide abundante e epitélio achatado. C: estimulada, epitélio colunar alto, pouco coloide e mitoses (m), padrão da hiperplasia por TSH elevado. Fonte: Gardner DG, Shoback D, Greenspan's Basic & Clinical Endocrinology, 10ª ed., fig. 7-4."},
  {"id":"vilar-31-1-patogenese-do-bocio-nodular-toxico","pos":82,"tema":"Bócio e Hipertireoidismo por Autonomia (BMN tóxico e adenoma tóxico)","origem":"04_hipertireoidismo_graves/patogenese_do_bocio_nodular_toxico__Vilar_p532.png","depoisDe":"pode **desencadear tireotoxicose** em glândulas já autônomas.","legenda":"Patogênese do bócio nodular tóxico: sobre a hiperplasia causada pela deficiência de iodo, ou de forma esporádica, surgem mutações do receptor do TSH ou da subunidade Gsα, que ativam continuamente a via do AMPc e levam à hiperfunção e ao crescimento autônomo da célula folicular. Fonte: adaptada de Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 31.1."},
  {"id":"imaging-1-8-adenoma-toxico","pos":82,"tema":"Bócio e Hipertireoidismo por Autonomia (BMN tóxico e adenoma tóxico)","origem":"04_hipertireoidismo_graves/adenoma_toxico_ultrassom_doppler_e_cintilografia__Imaging_p25.png","depoisDe":"associa-se a maior risco de FA, eventos cardiovasculares e perda óssea.","formato":"jpg","legenda":"Adenoma tóxico: nódulo sólido ao ultrassom em modo B e com Doppler colorido (a); na cintilografia com tecnécio-99m, nódulo hipercaptante (\"quente\") com supressão da captação no restante da glândula (b). Fonte: Pozzilli P, Lenzi A, Clarke BL, Young WF Jr, Imaging in Endocrinology, fig. 1.8."},
  {"id":"greenspan-7-2-corte-transversal-do-pescoco","pos":83,"tema":"Carcinoma Diferenciado de Tireoide (papilífero e folicular)","origem":"01_anatomia_embriologia_histologia/corte_transversal_do_pescoco_relacoes_da_tireoide__Greenspan_p198_PT.png","depoisDe":"O T pode ser **solitário (s)** ou **multicêntrico (m)**.","legenda":"Corte transversal do pescoço no nível da vértebra T1: tireoide em torno da traqueia, esôfago atrás, laríngeo recorrente no sulco traqueoesofágico e paratireoide atrás do lobo. A invasão das estruturas vizinhas define T4a (traqueia, esôfago, laríngeo recorrente) ou T4b (fáscia pré-vertebral, carótida). Fonte: traduzida de Gardner DG, Shoback D, Greenspan's Basic & Clinical Endocrinology, 10ª ed., fig. 7-2."},
  {"id":"williams-13-7-hashimoto-macroscopia-histologia","pos":85,"tema":"Tireoidites","origem":"03_hipotireoidismo/tireoidite_de_hashimoto_macroscopia_e_histologia__Williams_p514.png","depoisDe":"Formas **bociogênica** (bócio firme, irregular) e **atrófica**.","formato":"jpg","legenda":"Tireoidite de Hashimoto: tecido tireoidiano pálido à macroscopia (A); infiltrado linfocitário denso com centro germinativo (B); e fibrose densa com folículos atróficos e agregado linfoide (C). Fonte: Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 13.7."},
  {"id":"netter-2-21-tireoidite-hashimoto-e-riedel","pos":85,"tema":"Tireoidites","origem":"03_hipotireoidismo/tireoidite_de_hashimoto_e_tireoidite_de_riedel_patologia__Netter_p69_PT.png","depoisDe":"| **VHS** | **Normal** | **Normal** | **Elevado** |","formato":"jpg","legenda":"Tireoidite de Hashimoto: bócio lobulado, infiltrado linfocitário com centro germinativo e autoanticorpos anti-TPO e antitireoglobulina. Tireoidite de Riedel: glândula aumentada, com faixas de fibrose, que desloca ou comprime traqueia e esôfago; histologia com fibrose densa e infiltrado inflamatório. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-21."},
  {"id":"netter-2-10-orbitopatia-de-graves","pos":88,"tema":"Oftalmopatia de Graves (Doença Ocular Tireoidiana)","origem":"04_hipertireoidismo_graves/oftalmopatia_de_graves__Netter_p58_PT.png","depoisDe":"edema de papila — **ameaça à visão / emergência**.","formato":"jpg","legenda":"Orbitopatia de Graves: forma moderada a grave, com proptose, retração palpebral, edema periorbitário e hiperemia conjuntival (acima); teste de resiliência, que avalia a resistência do globo à retropulsão (à esquerda); forma grave progressiva, com quemose e úlcera de córnea (à direita). Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-10."},
  {"id":"williams-12-10-receptor-do-tsh-na-orbitopatia","pos":88,"tema":"Oftalmopatia de Graves (Doença Ocular Tireoidiana)","origem":"04_hipertireoidismo_graves/receptor_do_tsh_na_imunopatogenese_da_orbitopatia__Williams_p471_PT.png","depoisDe":"glicosaminoglicanos (ácido hialurônico)** — que puxa água e empurra o olho.","legenda":"Receptor do TSH na patogênese da orbitopatia: o TRAb ativa o receptor do TSH do fibroblasto orbital, em conjunto com o receptor de IGF-1 (vias do AMPc e da PI3K/Akt/mTOR), estimulando a adipogênese e a síntese de ácido hialurônico (AH), que expandem a gordura e os músculos orbitais. Fonte: traduzida e adaptada de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 12.10."},
  {"id":"williams-30-20-osteoporose-visao-geral","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"02_osteoporose_fisiopatologia_diagnostico/osteoporose_visao_geral_fraturas_microarquitetura__Williams_p1595_PT.png","depoisDe":"sobretudo vértebra, quadril, punho e úmero.","legenda":"Osteoporose: (A) radiografias das fraturas típicas de punho (rádio distal), vértebra e quadril; (B) microtomografia de osso normal e osteoporótico, com afinamento do córtex e deterioração da microarquitetura; embaixo, à direita, micrografias de osteoclastos (1, 2) e osteoblastos (3, 4). Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 30.20."},
  {"id":"williams-30-8-osteoblasto-osteoclasto-rankl-opg","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"01_biologia_ossea_e_remodelacao/diferenciacao_da_celula_mesenquimal_em_osteoblasto__Williams_p1576_PT.png","depoisDe":"A regulação negativa cabe à **osteoprotegerina (OPG)**, produzida pelo osteoblasto, que sequestra o RANK-L e impede sua ligação ao RANK.","legenda":"Origem das células ósseas: da célula-tronco hematopoiética vêm o pré-osteoclasto (com RANK) e o osteoclasto; da mesenquimal (CTM), o pré-osteoblasto, que amadurece em osteoblasto, ou o adipócito (via PPARγ). O pré-osteoblasto produz M-CSF (fator estimulador de colônias de macrófagos), IL-6, RANK-L e OPG. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 30.8."},
  {"id":"igaz-24-2-dxa-coluna-femur-radio","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"02_osteoporose_fisiopatologia_diagnostico/imagens_de_dxa_coluna_femur_e_radio__Igaz_p263_PT.png","depoisDe":"este indicado em **hiperparatireoidismo** ou quando o peso excede o limite do aparelho (**136–159 kg**).","formato":"jpg","legenda":"Densitometria óssea (DXA) nos três sítios de medida: (a) coluna lombar, com as regiões de L1 a L4; (b) fêmur proximal; (c) antebraço, com a região do terço distal do rádio (rádio 33%, de predomínio cortical) e a ultradistal (UD). Fonte: traduzida e adaptada de Igaz P (ed.), Practical Clinical Endocrinology, fig. 24.2."},
  {"id":"primer-40-5-genant-fraturas-vertebrais","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"02_osteoporose_fisiopatologia_diagnostico/classificacao_semiquantitativa_de_genant_fraturas_vertebrais__Primer_p346_PT.png","depoisDe":"**grau 3** — acima de 40%.","formato":"jpg","legenda":"Classificação semiquantitativa de Genant das fraturas vertebrais: grau 0 (normal), 0,5 (duvidosa), 1 (leve, redução de altura de 20–25%), 2 (moderada, 25–40%) e 3 (grave, > 40%); da esquerda para a direita, deformidades em cunha, bicôncava e por esmagamento. Fonte: traduzida de Bilezikian JP (ed.), Primer on the Metabolic Bone Diseases and Disorders of Mineral Metabolism, 9ª ed., fig. 40.5."},
  {"id":"netter-6-14-fatores-de-risco-osteoporose","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"02_osteoporose_fisiopatologia_diagnostico/fatores_de_risco_para_osteoporose__Netter_p180_PT.png","depoisDe":"rastreio de **hipogonadismo, hipercortisolismo, hipertireoidismo, hiperprolactinemia** e alterações de GH/IGF-1.","formato":"jpg","legenda":"Fatores de risco e causas de osteoporose: desuso, deficiência de cálcio e vitamina D, álcool, fármacos (glicocorticoides, heparina, metotrexato), doenças genéticas e crônicas, neoplasias da medula óssea e endocrinopatias (hipercortisolismo, hipogonadismo, hiperparatireoidismo, hipertireoidismo). Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-14."},
  {"id":"primer-71-2-efeitos-dos-bisfosfonatos","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"03_osteoporose_tratamento/efeitos_dos_bisfosfonatos_no_osso__Primer_p560_PT.png","depoisDe":"**Eficácia.** Reduzem fraturas vertebrais e não vertebrais — **exceto o ibandronato**, que não reduz fratura de quadril.","legenda":"Efeitos dos bisfosfonatos na osteoporose: queda rápida da remodelação óssea até um platô, ganho de DMO que continua na coluna lombar (CL) e se estabiliza no colo do fêmur (CF), benefício sobre a estrutura e o material ósseo, ação ainda incerta (?) sobre os osteócitos e redução do risco de fratura. Fonte: traduzida de Bilezikian JP (ed.), Primer on the Metabolic Bone Diseases and Disorders of Mineral Metabolism, 9ª ed., fig. 71.2."},
  {"id":"primer-72-1-mecanismo-do-denosumabe","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"03_osteoporose_tratamento/mecanismo_de_acao_do_denosumabe__Primer_p567_PT.png","depoisDe":"**Mecanismo.** Inibe o RANK-L e, portanto, a osteoclastogênese — **antirreabsortivo**. **Dose:** 60 mg SC a cada 6 meses. Reduz fratura vertebral e não vertebral, e é **seguro a longo prazo** (estudo FREEDOM).","formato":"jpg","legenda":"Mecanismo de ação do denosumabe: fatores que estimulam a reabsorção óssea levam os osteoblastos a liberar RANKL (ligante do RANK), que se liga ao RANK dos osteoclastos e estimula sua formação, atividade e sobrevida; o denosumabe, anticorpo monoclonal, liga-se ao RANKL e bloqueia esses efeitos. Fonte: traduzida de Bilezikian JP (ed.), Primer on the Metabolic Bone Diseases and Disorders of Mineral Metabolism, 9ª ed., fig. 72.1."},
  {"id":"vilar-86-2-via-wnt-esclerostina","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"01_biologia_ossea_e_remodelacao/via_wnt_beta_catenina_e_esclerostina__Vilar_p1535.png","depoisDe":"**Dose:** 210 mg SC **1×/mês por 12 meses**. Reduz fratura vertebral e não vertebral, e é recomendado no **muito alto risco**.","formato":"jpg","legenda":"Via Wnt/β-catenina. Ligada: o Wnt une o receptor Frizzled (FZD) ao correceptor LRP5/6, e a β-catenina escapa do complexo de destruição e ativa genes no núcleo. Desligada: a esclerostina (Scl), com o LRP4, bloqueia o LRP5/6, e a β-catenina é fosforilada, ubiquitinada (Ub) e degradada no proteossomo. Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 86.2."},
  {"id":"imaging-5-4-osteonecrose-de-mandibula","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"03_osteoporose_tratamento/osteonecrose_de_mandibula__Imaging_p118.png","depoisDe":"Osso mandibular **exposto por pelo menos 8 semanas**. É **muito rara**: **0,01 a 0,04%** dos usuários de terapia antirreabsortiva.","formato":"jpg","legenda":"Osteonecrose de mandíbula em forma grave: extensa exposição de osso necrótico, amarelado e irregular, na cavidade oral. É complicação rara da terapia antirreabsortiva (bisfosfonatos e denosumabe). Fonte: Pozzilli P, Lenzi A, Clarke BL, Young WF Jr, Imaging in Endocrinology, fig. 5.4."},
  {"id":"primer-71-4-fraturas-atipicas-de-femur","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"03_osteoporose_tratamento/fraturas_atipicas_de_femur_radiografias__Primer_p562.png","depoisDe":"espessamento periosteal ou endosteal localizado do córtex lateral no sítio da fratura (ASBMR, 2014).","legenda":"Fraturas atípicas de fêmur, subtrocantéricas e diafisárias, em pacientes com e sem uso de bisfosfonato (radiografias A–D): fraturas completas, de traço transverso ou oblíquo curto e sem cominuição. Fonte: Bilezikian JP (ed.), Primer on the Metabolic Bone Diseases and Disorders of Mineral Metabolism, 9ª ed., fig. 71.4."},
  {"id":"primer-5-4-osteocito-mecanotransducao","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"01_biologia_ossea_e_remodelacao/osteocitos_como_orquestradores_da_remodelacao__Primer_p67_PT.png","depoisDe":"Somam-se alterações pró-reabsortivas: ↑adiponectina, ↑PYY, ↓insulina, ↓estradiol, ↓leptina, ↓GIP, ↓grelina e ↓estrógenos periféricos.","legenda":"O osteócito orquestra a remodelação. A: sem carga (seta de deformação ε riscada), ele sinaliza às células de revestimento, que se retraem e dão lugar a osteoclastos. B: sob carga (ε), células de revestimento se desdiferenciam, ou precursores são recrutados, e forma-se osso novo. Sost é o gene da esclerostina. Fonte: traduzida de Bilezikian JP (ed.), Primer on the Metabolic Bone Diseases and Disorders of Mineral Metabolism, 9ª ed., fig. 5.4."},
  {"id":"vilar-86-7-laudo-dxa-coluna-lombar","pos":103,"tema":"Osteoporose: Diagnóstico e Tratamento","origem":"02_osteoporose_fisiopatologia_diagnostico/laudo_de_densitometria_da_coluna_lombar_t_score__Vilar_p1540.png","depoisDe":"| Osteoporose estabelecida | ≤ −2,5 + fratura por fragilidade |","formato":"jpg","legenda":"Laudo de densitometria (DXA) da coluna lombar de mulher de 71 anos: DMO de 0,854 g/cm² em L1–L4, com T-score −2,7 (faixa de osteoporose) e Z-score −0,4 (dentro do esperado para a idade). Fonte: adaptada de Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 86.7."},
  {"id":"netter-6-4-fisiopatologia-hiperparatireoidismo-primario","pos":104,"tema":"Hiperparatireoidismo Primário","origem":"04_hiperparatireoidismo/fisiopatologia_do_hiperparatireoidismo_primario__Netter_p170_PT.png","depoisDe":"**carcinoma de paratireoide** (suspeitar quando cálcio e PTH muito elevados com massa cervical palpável).","formato":"jpg","legenda":"Fisiopatologia do hiperparatireoidismo primário: o PTH elevado (adenoma, hiperplasia ou carcinoma) estimula a reabsorção óssea e tubular de cálcio e a síntese de 1,25(OH)2D; resultam hipercalcemia, fosfato (Pi) baixo ou normal e, pela carga filtrada maior, hipercalciúria, cálculos e nefrocalcinose. Fonte: traduzida e adaptada de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-4."},
  {"id":"netter-6-5-manifestacoes-hiperparatireoidismo-primario","pos":104,"tema":"Hiperparatireoidismo Primário","origem":"04_hiperparatireoidismo/patologia_e_manifestacoes_clinicas_do_hptp__Netter_p171_PT.png","depoisDe":"Na hipercalcemia significativa há **poliúria** e desidratação.","formato":"jpg","legenda":"Manifestações clássicas do hiperparatireoidismo primário (hoje a maioria é assintomática): nefrolitíase, nefrocalcinose, crânio em “sal e pimenta”, reabsorção subperiosteal, tumor marrom, perda da lâmina dura dentária, calcificação vascular, ceratopatia em faixa, úlcera péptica, pancreatite e NEM1. Fonte: traduzida e adaptada de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-5."},
  {"id":"imaging-5-7-reabsorcao-subperiosteal-falanges","pos":104,"tema":"Hiperparatireoidismo Primário","origem":"04_hiperparatireoidismo/reabsorcao_subperiosteal_das_falanges__Imaging_p121.png","depoisDe":"acro-osteólise e **coluna em Rugger-Jersey** (osteosclerose dos platôs vertebrais).","legenda":"Radiografia dos dedos com reabsorção subperiosteal nas margens das falanges (setas), que ficam irregulares e rendilhadas: achado radiológico clássico do hiperparatireoidismo. Fonte: Pozzilli P, Lenzi A, Clarke BL, Young WF Jr, Imaging in Endocrinology, fig. 5.7."},
  {"id":"vilar-82-13-adenoma-paratireoide-us-sestamibi","pos":104,"tema":"Hiperparatireoidismo Primário","origem":"04_hiperparatireoidismo/ultrassonografia_e_sestamibi_adenoma_de_paratireoide__Vilar_p1482.png","depoisDe":"No intraoperatório, **PTH aos 0 e 10 minutos, com meta de queda superior a 50%**.","legenda":"Adenoma de paratireoide na localização pré-operatória: nódulo posterior ao lobo direito da tireoide na ultrassonografia (A, seta), confirmado pela captação persistente na imagem tardia da cintilografia com 99mTc-sestamibi (B, seta). Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 82.13."},
  {"id":"matfin-23-2-investigacao-da-hipocalcemia","pos":105,"tema":"Hipoparatireoidismo e Hipocalcemia","origem":"05_hipoparatireoidismo_hipocalcemia/algoritmo_investigacao_da_hipocalcemia__Matfin_p405_PT.png","depoisDe":"Complementar com **fósforo** (alto no hipopara/pseudo-hipopara; baixo/normal na deficiência de vitamina D), **magnésio** (sempre **corrigir** antes de concluir!), **25-OH-vitamina D**, **função renal** e **ECG**.","legenda":"Investigação da hipocalcemia pelo PTH e fosfato (PO4): PTH alto com fosfato baixo sugere deficiência de vitamina D; PTH e fosfato altos, DRC, lise tumoral, rabdomiólise ou pseudo-hipoparatireoidismo; PTH baixo com fosfato alto, hipoparatireoidismo reversível (hipomagnesemia, cinacalcete) ou permanente. Fonte: traduzida de Matfin G (ed.), Endocrine and Metabolic Medical Emergencies, 2ª ed., fig. 23-2."},
  {"id":"netter-6-11-manifestacoes-da-hipocalcemia-aguda","pos":105,"tema":"Hipoparatireoidismo e Hipocalcemia","origem":"05_hipoparatireoidismo_hipocalcemia/manifestacoes_clinicas_da_hipocalcemia_aguda__Netter_p177_PT.png","depoisDe":"— flexão do punho, adução do polegar, flexão das metacarpofalângicas e extensão das interfalângicas proximais.","formato":"jpg","legenda":"Manifestações da hipocalcemia aguda: sinal de Trousseau (espasmo do carpo, a “mão de parteiro”, com o manguito insuflado), sinal de Chvostek (contração da musculatura facial à percussão do nervo facial), hiper-reflexia, laringoespasmo com estridor, convulsões, intervalo QT prolongado e papiledema. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-11."},
  {"id":"netter-6-10-fisiopatologia-do-hipoparatireoidismo","pos":105,"tema":"Hipoparatireoidismo e Hipocalcemia","origem":"05_hipoparatireoidismo_hipocalcemia/fisiopatologia_do_hipoparatireoidismo__Netter_p176_PT.png","depoisDe":"sem tratamento, porém, a calciúria de 24 h costuma ser baixa ou normal (carga filtrada reduzida), e a **hipercalciúria** surge quando o tratamento eleva a calcemia.","formato":"jpg","legenda":"Fisiopatologia do hipoparatireoidismo, em geral pós-operatório: sem PTH, caem a produção renal de 1,25(OH)2D e a absorção intestinal de cálcio, e o túbulo reabsorve menos cálcio e mais fosfato (Pi). Resultam hipocalcemia, hiperfosfatemia, calciúria baixa e densidade óssea normal ou levemente aumentada. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-10."},
  {"id":"netter-6-12-fisiopatologia-do-pseudo-hipoparatireoidismo","pos":105,"tema":"Hipoparatireoidismo e Hipocalcemia","origem":"05_hipoparatireoidismo_hipocalcemia/fisiopatologia_do_pseudo_hipoparatireoidismo__Netter_p178_PT.png","depoisDe":"⚠️ **O que separa hipoparatireoidismo de pseudo-hipoparatireoidismo é o PTH:** baixo no primeiro, **alto** no segundo (resistência ao hormônio).","formato":"jpg","legenda":"Fisiopatologia do pseudo-hipoparatireoidismo: a resistência ao PTH no túbulo renal (e, na maioria dos casos, no osso) reduz a reabsorção de cálcio e a produção de 1,25(OH)2D e aumenta a reabsorção de fosfato (Pi); a hipocalcemia leva à hiperplasia das paratireoides, com PTH alto, porém ineficaz. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-12."},
  {"id":"greenspan-8-19-maos-no-pseudo-hipoparatireoidismo","pos":105,"tema":"Hipoparatireoidismo e Hipocalcemia","origem":"05_hipoparatireoidismo_hipocalcemia/maos_no_pseudo_hipoparatireoidismo__Greenspan_p294.png","depoisDe":"Somam-se resistência ao TSH (**hipotireoidismo**) e ao FSH/LH (**atraso puberal**).","legenda":"Mãos no pseudo-hipoparatireoidismo com osteodistrofia de Albright: quarto dedo curto (A); com a mão fechada, falta o relevo da cabeça do quarto metacarpo, o “nó” do dedo (B); na radiografia, quarto metacarpo encurtado (C). Fonte: Gardner DG, Shoback D, Greenspan's Basic & Clinical Endocrinology, 10ª ed., fig. 8-19."},
  {"id":"greenspan-8-13-ciclo-vicioso-da-hipercalcemia","pos":106,"tema":"Hipercalcemia: Diagnóstico e Manejo","origem":"06_hipercalcemia/ciclo_vicioso_da_hipercalcemia__Greenspan_p282_PT.png","depoisDe":"A hipercalcemia crônica também favorece calcificações vasculares e nefrocalcinose.","legenda":"Ciclo vicioso da hipercalcemia: anorexia, náuseas e vômitos, somados à perda renal de sal e água, contraem o volume do líquido extracelular (LEC); a contração reduz a excreção renal de cálcio e agrava a hipercalcemia. Fonte: traduzida de Gardner DG, Shoback D, Greenspan's Basic & Clinical Endocrinology, 10ª ed., fig. 8-13."},
  {"id":"williams-29-28-abordagem-da-hipercalcemia","pos":106,"tema":"Hipercalcemia: Diagnóstico e Manejo","origem":"06_hipercalcemia/abordagem_do_paciente_com_hipercalcemia__Williams_p1530_PT.png","depoisDe":"| Suprimido | Outras | Hipertireoidismo, imobilização, leite-álcali |","legenda":"Abordagem da hipercalcemia: confirmar com cálcio total e iônico (cálcio normal sugere hemoconcentração ou alteração das proteínas séricas), avaliar a clínica e dosar o PTH. PTH normal ou alto indica causa PTH-dependente; PTH baixo, causa PTH-independente, com pesquisa de neoplasia oculta. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 29.28."},
  {"id":"netter-6-6-diagnostico-diferencial-das-hipercalcemias","pos":106,"tema":"Hipercalcemia: Diagnóstico e Manejo","origem":"06_hipercalcemia/diagnostico_diferencial_das_hipercalcemias__Netter_p172_PT.png","depoisDe":"na intoxicação sobe **a 25-OH**, muito elevada, e a 1,25 costuma ficar normal ou pouco alterada.","legenda":"Diagnóstico diferencial das hipercalcemias pelo cálcio, fosfato (Pi), PTH, 25(OH)D e 1,25(OH)2D séricos em hiperparatireoidismo primário, metástases ósseas, mieloma, hipercalcemia humoral (PTHrP), granulomatoses, hipertireoidismo, intoxicação por vitamina D, leite-álcali e imobilização (N = normal). Fonte: traduzida e adaptada de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-6."},
  {"id":"netter-6-18-raquitismo-osteomalacia-carenciais","pos":107,"tema":"Deficiência e Metabolismo da Vitamina D","origem":"07_vitamina_d_raquitismo_osteomalacia/raquitismo_e_osteomalacia_por_deficiencia_nutricional__Netter_p184_PT.png","depoisDe":"(anticonvulsivantes, glicocorticoide, antirretrovirais, rifampicina); baixa ingestão.","formato":"jpg","legenda":"Raquitismo e osteomalácia carenciais: causas da falta de vitamina D e cálcio (pouco sol, dieta pobre, má absorção, anticonvulsivantes, gestação e lactação) e consequências: cálcio normal-baixo, PTH alto, perda renal de fósforo, reabsorção óssea, fosfatase alcalina elevada e osteoide não mineralizado. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-18."},
  {"id":"primer-89-1-calcio-fosfato-osteoporose-osteomalacia","pos":107,"tema":"Deficiência e Metabolismo da Vitamina D","origem":"07_vitamina_d_raquitismo_osteomalacia/fisiopatologia_calcio_fosfato_osteoporose_x_osteomalacia__Primer_p698_PT.png","depoisDe":"O calcitriol é um marcador ruim de status e não deve ser pedido para diagnóstico de deficiência.","legenda":"Carência de cálcio e vitamina D: (A) leve, com 25OHD baixa, PTH alto e mineralização normal (osteoporose); (B, C) osteomalácia, com cálcio e fósforo baixos, PTH muito alto e mineralização reduzida, por falta de vitamina D (1,25(OH)2D baixa) ou má absorção de cálcio (25OHD normal, 1,25(OH)2D alta). Fonte: traduzida de Bilezikian JP (ed.), Primer on the Metabolic Bone Diseases and Disorders of Mineral Metabolism, 9ª ed., fig. 89.1."},
  {"id":"netter-6-23-doenca-de-paget-manifestacoes","pos":108,"tema":"Doença de Paget Óssea","origem":"08_doenca_de_paget_e_doencas_osseas_raras/doenca_de_paget_manifestacoes__Netter_p189_PT.png","depoisDe":"suspeitar quando há **piora súbita da dor** ou massa de partes moles.","formato":"jpg","legenda":"Doença de Paget avançada: crânio aumentado, surdez (mão em concha na orelha), cifose e membros encurvados. Embaixo: osteoporose circunscrita do crânio, crânio espessado com hidrocefalia, tíbia espessada e arqueada com cunha lítica e fratura “em giz” em consolidação. Fonte: traduzida e adaptada de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-23."},
  {"id":"primer-38-2-cintilografia-paget-poliostotico","pos":108,"tema":"Doença de Paget Óssea","origem":"08_doenca_de_paget_e_doencas_osseas_raras/cintilografia_ossea_paget_poliostotico__Primer_p327.png","depoisDe":"a biópsia fica para a dúvida diagnóstica ou a suspeita de malignidade (Ralston, JBMR 2019).","legenda":"Cintilografia óssea na doença de Paget poliostótica: hipercaptação em escápula, vértebras e pelve nas imagens de corpo inteiro (a mancha central na pelve é a bexiga); à direita, detalhe da coluna com vértebra acometida (seta). Fonte: Bilezikian JP (ed.), Primer on the Metabolic Bone Diseases and Disorders of Mineral Metabolism, 9ª ed., fig. 38.2."},
  {"id":"imaging-5-22-paget-espessamento-cortical-femur","pos":108,"tema":"Doença de Paget Óssea","origem":"08_doenca_de_paget_e_doencas_osseas_raras/paget_espessamento_cortical_e_trabecular_do_femur__Imaging_p130.png","depoisDe":"**fria (reparadora)** — espessamento cortical e alargamento ósseo.","legenda":"Doença de Paget no fêmur proximal esquerdo (à direita na imagem): córtex espessado, trabéculas grosseiras e osso alargado, alterações das fases mista e fria (reparadora). Fonte: Pozzilli P, Lenzi A, Clarke BL, Young WF Jr, Imaging in Endocrinology, fig. 5.22."},
  {"id":"imaging-5-23-paget-lesao-em-folha-de-grama","pos":108,"tema":"Doença de Paget Óssea","origem":"08_doenca_de_paget_e_doencas_osseas_raras/paget_lesao_em_folha_de_grama__Imaging_p131.png","depoisDe":"na pelve, o **sinal do colarinho** da linha ileopectínea.","legenda":"Doença de Paget na fase quente (lítica): borda de reabsorção em V, em “folha de grama” ou chama de vela (sinal da lâmina de folha), avançando pela diáfise do fêmur (setas). Fonte: Pozzilli P, Lenzi A, Clarke BL, Young WF Jr, Imaging in Endocrinology, fig. 5.23."},
  {"id":"imaging-5-29-biopsia-osteomalacia","pos":109,"tema":"Osteomalácia e Raquitismo","origem":"07_vitamina_d_raquitismo_osteomalacia/biopsia_ossea_na_osteomalacia_excesso_de_osteoide__Imaging_p135.png","depoisDe":"(o osso é normal em qualidade, mas em menor quantidade).","formato":"jpg","legenda":"Biópsia de crista ilíaca na osteomalácia (tricrômio de Goldner): o osso mineralizado cora em verde e o osteoide não mineralizado, em vermelho, forma faixas largas sobre as trabéculas, com aumento da espessura, da superfície e do volume do osteoide. Fonte: Pozzilli P, Lenzi A, Clarke BL, Young WF Jr, Imaging in Endocrinology, fig. 5.29."},
  {"id":"primer-39-3-dupla-marcacao-tetraciclina","pos":109,"tema":"Osteomalácia e Raquitismo","origem":"01_biologia_ossea_e_remodelacao/histomorfometria_dupla_marcacao_com_tetraciclina__Primer_p333.png","depoisDe":"A **biópsia óssea com dupla marcação por tetraciclina** é o padrão-ouro, raramente necessária.","formato":"jpg","legenda":"Biópsia óssea com dupla marcação por tetraciclina, à fluorescência: cada linha marca a frente de mineralização num dos dois cursos do antibiótico, e a distância entre elas, dividida pelo intervalo entre os cursos, dá a taxa de aposição mineral. Na osteomalácia, as marcas ficam difusas ou ausentes. Fonte: Bilezikian JP (ed.), Primer on the Metabolic Bone Diseases and Disorders of Mineral Metabolism, 9ª ed., fig. 39.3."},
  {"id":"vilar-90-8-zonas-de-looser","pos":109,"tema":"Osteomalácia e Raquitismo","origem":"07_vitamina_d_raquitismo_osteomalacia/zonas_de_looser_pseudofraturas__Vilar_p1605.png","depoisDe":"e afilamento cortical são o achado radiográfico característico do adulto; nas crianças, o **\"cupping\"** metafisário.","legenda":"Zonas de Looser (pseudofraturas) na osteomalácia: faixas radiotransparentes perpendiculares à cortical (setas), na face medial do colo do fêmur (A) e na borda lateral da escápula (B). Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 90.8."},
  {"id":"williams-30-9-osteoblasto-a-osteocito-marcadores","pos":109,"tema":"Osteomalácia e Raquitismo","origem":"01_biologia_ossea_e_remodelacao/do_osteoblasto_ao_osteocito_marcadores__Williams_p1577_PT.png","depoisDe":"a principal é a **mutação inativadora do PHEX**, ligada ao X, que impede a degradação dos sinalizadores que estimulam a produção de FGF-23.","legenda":"Do pré-osteoblasto ao osteócito maduro, com os marcadores de cada fase: o osteoblasto expressa Cbfa1 (Runx2), osterix e fosfatase alcalina; o osteócito osteoide, PHEX e MEPE; o mineralizante, DMP1; e o osteócito maduro, já no osso mineralizado, esclerostina e FGF23. Fonte: traduzida de Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 30.9."},
  {"id":"netter-6-27-hipofosfatasia","pos":109,"tema":"Osteomalácia e Raquitismo","origem":"08_doenca_de_paget_e_doencas_osseas_raras/hipofosfatasia__Netter_p193_PT.png","depoisDe":"é análogo do pirofosfato, o próprio inibidor da mineralização que já está acumulado.","formato":"jpg","legenda":"Hipofosfatasia: formas infantil, da infância e do adulto. Com a fosfatase alcalina muito baixa, o pirofosfato inorgânico (PPi) não é hidrolisado, acumula-se e inibe a mineralização; PPi, fosfoetanolamina e piridoxal-5-fosfato sobem no plasma, e PPi e fosfoetanolamina, na urina. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-27."},
  {"id":"netter-2-5-tireoide-ectopica","pos":142,"tema":"Hipotireoidismo Congênito","origem":"01_anatomia_embriologia_histologia/anomalias_congenitas_tireoide_ectopica_e_ducto_tireoglosso__Netter_p53_PT.png","depoisDe":"Os demais ~35% têm glândula tópica (*in situ*), com disormonogênese hereditária em menos da metade deles (ENDO-ERN 2021).","formato":"jpg","legenda":"Tecido tireoidiano ectópico ao longo do trajeto tireoglosso, da língua (lingual, intralingual, sublingual) ao mediastino (subesternal), além do cisto tireoglosso. Embaixo, tireoide lingual vista pela boca e na cintilografia, com captação na base da língua e nenhuma no leito tireoidiano. Fonte: traduzida de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 2-5."},
  {"id":"abeso2016-1-2-curvas-imc-oms-meninas","pos":145,"tema":"Obesidade na Infância e Adolescência","origem":"08_obesidade_infantil_e_cancer/curvas_de_imc_oms_meninas_0_a_19_anos__Diretriz2016_p133.png","depoisDe":"sendo obesidade grave definida como **IMC ≥ 120% do P95 ou escore-Z ≥ +3**.","formato":"jpg","legenda":"Curvas da OMS de IMC para idade em meninas, em escore z, de 0 a 5 anos (OMS 2006) e de 5 a 19 anos (OMS 2007). Abaixo de 5 anos, sobrepeso > +2 e obesidade > +3; de 5 a 19 anos, sobrepeso > +1, obesidade > +2 e obesidade grave ≥ +3. Fonte: ABESO, Diretrizes Brasileiras de Obesidade 2016, 4ª ed., figs. 1 e 2."},
  {"id":"kopelman-26-2-exame-fisico-crianca-com-obesidade","pos":145,"tema":"Obesidade na Infância e Adolescência","origem":"08_obesidade_infantil_e_cancer/exame_fisico_da_crianca_e_do_adolescente_com_obesidade__ClinicalObesity_p355_PT.png","depoisDe":"estágio puberal e busca ativa de geno varo/valgo, pé plano e **epifisiólise da cabeça do fêmur**.","legenda":"Roteiro do exame físico da criança e do adolescente com obesidade, por região: dismorfias e aspecto cushingoide, acantose, fundoscopia (HII, hipertensão intracraniana idiopática), via aérea e pescoço (AOS, apneia obstrutiva do sono), PA com manguito adequado, abdome, puberdade e membros inferiores. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 26.2."},
  {"id":"abeso2016-3-4-curvas-imc-oms-meninos","pos":145,"tema":"Obesidade na Infância e Adolescência","origem":"08_obesidade_infantil_e_cancer/curvas_de_imc_oms_meninos_0_a_19_anos__Diretriz2016_p134.png","depoisDe":"| Síndrome metabólica | 6–9 anos | **não se diagnostica** |","formato":"jpg","legenda":"Curvas da OMS de IMC para idade em meninos, em escore z, de 0 a 5 anos (OMS 2006) e de 5 a 19 anos (OMS 2007), com os mesmos cortes usados nas meninas: obesidade acima de +3 antes dos 5 anos e acima de +2 dos 5 aos 19. Fonte: ABESO, Diretrizes Brasileiras de Obesidade 2016, 4ª ed., figs. 3 e 4."},
  {"id":"kopelman-27-1-niveis-de-tratamento-obesidade-infantil","pos":146,"tema":"Tratamento da Obesidade na Infância e Adolescência","origem":"08_obesidade_infantil_e_cancer/opcoes_e_niveis_de_tratamento_da_obesidade_infantil__ClinicalObesity_p363_PT.png","depoisDe":"A farmacoterapia e a cirurgia são adjuvantes, não substitutivas.","legenda":"Tratamento escalonado da obesidade infantil: estilo de vida para todos com excesso de peso, na atenção primária e na comunidade; farmacoterapia para adolescentes com obesidade (centro secundário ou terciário) e cirurgia bariátrica na obesidade grave (centro terciário), ambas somadas ao estilo de vida. Fonte: traduzida de Kopelman PG, Caterson ID, Dietz WH (eds.), Clinical Obesity in Adults and Children, 4ª ed., fig. 27.1."},
  {"id":"netter-6-21-raquitismo-na-infancia","pos":147,"tema":"Raquitismo","origem":"07_vitamina_d_raquitismo_osteomalacia/manifestacoes_clinicas_do_raquitismo_na_infancia__Netter_p187_PT.png","depoisDe":"no calciopênico grave, **hipocalcemia sintomática** (tetania, convulsões).","formato":"jpg","legenda":"Raquitismo na infância: crescimento prejudicado, craniotabes, fronte olímpica (bossa frontal), defeitos dentários, peito de pombo, rosário raquítico, sulco de Harrison, extremidades dos ossos longos alargadas, coxa vara e geno varo; ao lado, radiografias de joelhos, mão e pelve e histologia óssea. Fonte: traduzida e adaptada de Young WF Jr, The Netter Collection of Medical Illustrations: Endocrine System, 2ª ed., prancha 6-21."},
  {"id":"williams-31-7-hipofosfatasia-radiografias","pos":147,"tema":"Raquitismo","origem":"08_doenca_de_paget_e_doencas_osseas_raras/hipofosfatasia_achados_radiologicos__Williams_p1638.png","depoisDe":"**fosfatase alcalina baixa** com clínica semelhante sugere **hipofosfatasia** (defeito da fosfatase alcalina, não raquitismo carencial).","legenda":"Hipofosfatasia, que imita o raquitismo mas cursa com fosfatase alcalina baixa: A, alterações metafisárias semelhantes às do raquitismo nos membros inferiores de uma criança (setas); B, área lucente em “língua” na metáfise distal do fêmur (seta); C, pseudofratura na tíbia (seta). Fonte: Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 31.7."},
  {"id":"williams-31-6-raquitismo-carencial-x-ligado-ao-x","pos":147,"tema":"Raquitismo","origem":"07_vitamina_d_raquitismo_osteomalacia/raquitismo_nutricional_x_hipofosfatemico_ligado_ao_x__Williams_p1633.png","depoisDe":"| Tratamento | Vitamina D + cálcio | Burosumabe (preferido) ou fosfato + calcitriol |","legenda":"Raquitismo em crianças de 5 anos: (A) por deficiência nutricional de vitamina D, com metáfises alargadas, irregulares e desfiadas nos joelhos; (B) hipofosfatêmico ligado ao X (XLH), com encurvamento de fêmures e tíbias (geno varo) e alterações metafisárias mais discretas. Fonte: Melmed S et al., Williams Textbook of Endocrinology, 14ª ed., fig. 31.6."},
  {"id":"apovian-6-1-modelo-centrado-em-complicacoes-aace","pos":217,"tema":"Abordagem Centrada em Complicações","origem":"04_diagnostico_classificacao_estadiamento/modelo_centrado_em_complicacoes_estadiamento_aace__ClinicalManagementObesity_p126_PT.png","depoisDe":" adiposidade. Quem mais se beneficia de fármaco ou cirurgia é **quem já tem complicação**, não quem tem o IMC mais alto.","legenda":"Modelo centrado em complicações (AACE): antropometria (IMC e cintura) e pesquisa de complicações definem o estágio (0, nenhuma; 1, leves a moderadas; 2, graves), que orienta a fase de prevenção e a intensidade do tratamento. Fentermina e fentermina/topiramato não são aprovadas no Brasil. Fonte: traduzida de Apovian CM, Aronne LJ, Barenbaum SR, Clinical Management of Obesity, 3ª ed., fig. 6.1."},
  {"id":"apovian-tabela-6-1-estadiamento-edmonton-eoss","pos":217,"tema":"Abordagem Centrada em Complicações","origem":"04_diagnostico_classificacao_estadiamento/sistema_de_estadiamento_de_edmonton_eoss__ClinicalManagementObesity_p132_PT.png","depoisDe":"- **4** — incapacidade **grave**, potencialmente terminal.","legenda":"Sistema de Estadiamento da Obesidade de Edmonton (EOSS): estágios 0 a 4 pela gravidade das alterações cardiometabólicas e das limitações funcionais e do bem-estar; DHGNA (doença hepática gordurosa não alcoólica) é o nome antigo da DHEM. O domínio de saúde mental do EOSS não aparece na tabela. Fonte: traduzida de Apovian CM, Aronne LJ, Barenbaum SR, Clinical Management of Obesity, 3ª ed., tabela 6.1."},
  {"id":"diretriz2025-1-tratamento-por-risco-cardiovascular","pos":217,"tema":"Abordagem Centrada em Complicações","origem":"06_tratamento_clinico_e_farmacologico/tratamento_da_obesidade_conforme_o_risco_cardiovascular__Diretriz2025_p12.png","depoisDe":"estadiar é o que otimiza a relação benefício/risco de cada paciente.","legenda":"Intervenções da diretriz brasileira de 2025 por categoria de risco cardiovascular, da insuficiência cardíaca (IC) estabelecida ao risco moderado; a cor do marcador indica a força da recomendação. MEV, mudança de estilo de vida; iSGLT2, inibidor do SGLT2; HIC, hospitalização por IC. Fonte: Saraiva JFK et al., Diretriz Brasileira Baseada em Evidências de 2025 para o Manejo da Obesidade (ABESO/SBD/SBC/SBEM/ABS), fig. 1."},
  {"id":"vilar-76-4-fisiopatologia-dhem","pos":225,"tema":"DHEM: Esteatose Hepática Metabólica, Fibrose e MASH","origem":"05_complicacoes/fisiopatologia_da_doenca_hepatica_esteatotica_metabolica__Vilar_p1389.png","depoisDe":"Fisiopatologia: resistência insulínica e gordura visceral → **lipídio ectópico**, **↓ beta-oxidação**, **↑ ROS e citocinas** e toxinas da disbiose.","legenda":"Fisiopatologia da DHEM: o tecido adiposo (TA) disfuncional, pouco expansível no subcutâneo (TAS) e aumentado no visceral (TAV), envia ácidos graxos livres (AGL) a fígado, músculo e pâncreas; gordura ectópica e resistência à insulina (RI) levam a dislipidemia, DM2 e hipertensão. RG, resistência ao glucagon. Fonte: Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 76.4."},
  {"id":"vilar-76-1-historia-natural-doenca-hepatica-esteatotica","pos":225,"tema":"DHEM: Esteatose Hepática Metabólica, Fibrose e MASH","origem":"05_complicacoes/historia_natural_da_doenca_hepatica_esteatotica__Vilar_p1386.png","depoisDe":"a cada **~7 anos** na MASH (Singh, CGH 2015).","legenda":"História natural da doença hepática esteatótica: da esteatose simples à esteato-hepatite (12 a 40%), desta à cirrose (15 a 25%) e da cirrose ao hepatocarcinoma (7%), que também pode surgir da esteato-hepatite sem cirrose; as setas pretas indicam regressão possível. Fonte: adaptada de Vilar L (ed.), Endocrinologia Clínica, 8ª ed., fig. 76.1."},
];
